#!/usr/bin/env node
// Regenerates or checks the web console's consumer contract (ADR-0025):
// contracts/consumers/web/*.contract.json, drift.json and uncontracted.json.
//
//   node scripts/api-contract.mjs            summary only, writes nothing
//   node scripts/api-contract.mjs --write    rewrite the files from web/app + docs/api/openapi.json
//   node scripts/api-contract.mjs --check    exit 1 when the committed files differ from a regeneration
//
// Hand-written interactions: contracts/consumers/web/manual.contract.json (same format as the
// generated files, ids prefixed "manual-") is never generated, rewritten or deleted. Use it only for
// a call the extractor cannot read and that no wrapper-following can recover (a truly generic helper
// whose callers pass runtime strings); name the real endpoint, status and required fields, which
// ConsumerContractVerificationTest checks against the provider like any other file, and say in the
// interaction's "//" why it is manual. consumerContract.test.ts exempts it from the stale-entry check.
// Wrapper functions (a function forwarding a parameter into apiFetch / fetch) are followed
// automatically: see scripts/api-contract/calls.mjs.
//
// Run from web/ (needs node_modules for the TypeScript compiler). The provider
// side, core's ConsumerContractVerificationTest, verifies every interaction
// against the OpenAPI document generated from the controllers; the vitest
// app/lib/api/consumerContract.test.ts fails when a call site is not covered.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { generate } from "./api-contract/generate.mjs";

const webRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const repoRoot = path.resolve(webRoot, "..");
const outDir = path.join(repoRoot, "contracts", "consumers", "web");
const spec = JSON.parse(fs.readFileSync(path.join(repoRoot, "docs", "api", "openapi.json"), "utf8"));
const mode = process.argv[2] ?? "";
const MANUAL = "manual.contract.json";

const result = generate(webRoot, spec);
const wanted = new Map();
for (const [name, doc] of Object.entries(result.files)) wanted.set(name, doc);
wanted.set("drift.json", {
  "//": "Fields the console reads or sends that the provider schema does not declare. Generated by web/scripts/api-contract.mjs; fix one side and regenerate, this list only shrinks.",
  drift: result.drift,
});
wanted.set("uncontracted.json", {
  "//": "Call sites the extractor cannot turn into an interaction: a non-literal URL (count per file) or a route the OpenAPI document does not declare. Generated by web/scripts/api-contract.mjs.",
  ...result.uncontracted,
});
const render = (doc) => JSON.stringify(doc, null, 2) + "\n";

const interactions = Object.values(result.files).reduce((n, d) => n + d.interactions.length, 0);
const dynamicSites = Object.values(result.uncontracted.dynamicCallSites).reduce((n, c) => n + c, 0);
console.log(
  `web contract: ${interactions} interactions in ${Object.keys(result.files).length} files, ` +
    `${result.drift.length} drift entries, ${result.uncontracted.unmatched.length} unmatched calls, ` +
    `${dynamicSites} dynamic call sites`
);

const existing = fs.existsSync(outDir) ? fs.readdirSync(outDir).filter((n) => n.endsWith(".json")) : [];
if (mode === "--write") {
  fs.mkdirSync(outDir, { recursive: true });
  for (const name of existing) if (!wanted.has(name) && name !== MANUAL) fs.rmSync(path.join(outDir, name));
  for (const [name, doc] of wanted) fs.writeFileSync(path.join(outDir, name), render(doc));
  console.log(`wrote ${wanted.size} files to ${path.relative(repoRoot, outDir)}`);
} else if (mode === "--check") {
  const problems = [];
  for (const name of existing) if (!wanted.has(name) && name !== MANUAL) problems.push(`stale file ${name}`);
  for (const [name, doc] of wanted) {
    const file = path.join(outDir, name);
    if (!fs.existsSync(file)) problems.push(`missing ${name}`);
    else if (fs.readFileSync(file, "utf8") !== render(doc)) problems.push(`out of date ${name}`);
  }
  if (problems.length > 0) {
    console.error(problems.join("\n"));
    console.error("Run `node scripts/api-contract.mjs --write` from web/ and commit contracts/consumers/web.");
    process.exit(1);
  }
  console.log("contracts/consumers/web is current");
} else if (mode !== "") {
  console.error(`unknown option ${mode}; use --write or --check`);
  process.exit(2);
}
